function normalizeLocale(value: string): Locale {
  if (value === "hi") {
    return "hi";
  }

  if (value === "gu") {
    return "gu";
  }

  return "en";
}

export default function RegisterPage() {
  const router = useRouter();
  const params = useParams<{ locale: string }>();

  const locale = normalizeLocale(params?.locale || "en");
  const t = translations[locale];

  const [form, setForm] = useState({
    firstName: "",
    lastName: "",
    fatherFullName: "",
    motherFullName: "",
    email: "",
    password: "",
    confirmPassword: "",
    phone: "",
    whatsappNumber: "",
    gender: "",
    dateOfBirth: "",
    address: "",
    city: "",
    state: "",
    country: "India",
    pincode: "",
  });

  const [countryCode, setCountryCode] = useState("IN");
  const [stateCode, setStateCode] = useState("");
  const [countries, setCountries] = useState<any[]>([]);
  const [states, setStates] = useState<any[]>([]);
  const [cities, setCities] = useState<any[]>([]);
  const [loadingCountries, setLoadingCountries] = useState(true);
  const [loadingStates, setLoadingStates] = useState(false);
  const [loadingCities, setLoadingCities] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    try {
      setLoadingCountries(true);

      const data = Countries.getCountries();

      const sorted = [...data].sort((a, b) =>
        a.name.localeCompare(b.name)
      );

      setCountries(sorted);

      const india = sorted.find(
        (country) => country.iso2 === "IN"
      );

      if (india) {
        setCountryCode(india.iso2);

        setForm((prev) => ({
          ...prev,
          country: india.name,
        }));
      }
    } catch (error) {
      console.error("Unable to load countries:", error);
      setCountries([]);
    } finally {
      setLoadingCountries(false);
    }
  }, []);

  useEffect(() => {
    if (!countryCode) {
      setStates([]);
      setCities([]);
      setStateCode("");
      return;
    }

    try {
      setLoadingStates(true);

      const data = States.getStates({
        filters: {
          country_code: countryCode,
        },
      });

      const sorted = [...data].sort((a, b) =>
        a.name.localeCompare(b.name)
      );

      setStates(sorted);
      setStateCode("");
      setCities([]);

      setForm((prev) => ({
        ...prev,
        state: "",
        city: "",
      }));
    } catch (error) {
      console.error("Unable to load states:", error);
      setStates([]);
    } finally {
      setLoadingStates(false);
    }
  }, [countryCode]);

  useEffect(() => {
    if (!countryCode || !stateCode) {
      setCities([]);
      return;
    }

    try {
      setLoadingCities(true);

      const packageCities = Cities.getCities({
      filters: {
        country_code: countryCode,
        state_code: stateCode,
      },
    });

    // Keep package City objects untouched.
    // Add missing cities only to the dropdown options.
    const cityOptions = [
      ...packageCities.map((city) => ({
        name: city.name,
      })),
      ...(countryCode === "GB" && stateCode === "KEN"
        ? [{ name: "Canterbury" }]
        : []),
    ];

    const uniqueCities = Array.from(
      new Map(
        cityOptions.map((city) => [
          city.name.toLowerCase(),
          city,
        ])
      ).values()
    );

    const sorted = uniqueCities.sort((a, b) =>
      a.name.localeCompare(b.name)
    );

    setCities(sorted);
    } catch (error) {
      console.error("Unable to load cities:", error);
      setCities([]);
    } finally {
      setLoadingCities(false);
    }
  }, [countryCode, stateCode]);
  function updateField(
    field: keyof typeof form,
    value: string
  ) {
    setForm((current) => ({
      ...current,
      [field]: value,
    }));
  }

  async function handleSubmit(
    event: FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    setError("");
    setSuccess("");

    if (form.password !== form.confirmPassword) {
      setError(t.passwordMismatch);
      return;
    }

    if (form.password.length < 8) {
      setError(t.passwordLength);
      return;
    }

    setLoading(true);

    try {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          firstName: form.firstName,
          lastName: form.lastName,
          fatherFullName: form.fatherFullName,
          motherFullName: form.motherFullName,
          email: form.email,
          password: form.password,
          phone: form.phone,
          whatsappNumber: form.whatsappNumber,
          gender: form.gender,
          dateOfBirth: form.dateOfBirth,
          address: form.address,
          city: form.city,
          state: form.state,
          country: form.country,
          pincode: form.pincode,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(
          data?.message || t.registrationFailed
        );
        setLoading(false);
        return;
      }

      setSuccess(
        data?.message || t.registrationSuccess
      );

      setTimeout(() => {
        router.push(`/${locale}/login`);
      }, 1800);
    } catch (error) {
      console.error("Registration error:", error);

      setError(t.genericError);
      setLoading(false);
    }
  }

  return (
    <main className="min-h-screen bg-gray-100 px-4 py-10 dark:bg-[#3b0710]">
      <div className="mx-auto w-full max-w-4xl">
        <div className="rounded-2xl bg-white p-6 shadow-xl sm:p-8 dark:bg-[#64131f]">
          <div className="mb-8 text-center">
            <h1 className="text-3xl font-bold text-red-800 dark:text-red-100">
              {t.title}
            </h1>

            <p className="mt-2 text-gray-600 dark:text-red-100/80">
              {t.subtitle}
            </p>
          </div>

          <form
            onSubmit={handleSubmit}
            className="space-y-8"
          >
            <section>
              <h2 className="mb-4 border-b border-gray-200 pb-2 text-lg font-semibold text-gray-900 dark:border-red-300/20 dark:text-red-50">
                {t.basicInformation}
              </h2>

              <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <div>
                  <label
                    htmlFor="firstName"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.firstName} *
                  </label>

                  <input
                    id="firstName"
                    type="text"
                    value={form.firstName}
                    onChange={(e) =>
                      updateField(
                        "firstName",
                        e.target.value
                      )
                    }
                    placeholder={t.firstNamePlaceholder}
                    required
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none transition-colors placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50 dark:focus:border-red-300 dark:focus:ring-red-300/20"
                  />
                </div>

                <div>
                  <label
                    htmlFor="lastName"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.lastName} *
                  </label>

                  <input
                    id="lastName"
                    type="text"
                    value={form.lastName}
                    onChange={(e) =>
                      updateField(
                        "lastName",
                        e.target.value
                      )
                    }
                    placeholder={t.lastNamePlaceholder}
                    required
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none transition-colors placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50 dark:focus:border-red-300 dark:focus:ring-red-300/20"
                  />
                </div>

                <div>
                  <label
                    htmlFor="fatherFullName"
                    className="mb-2 block text-sm font-semibold text-[#5b3a00] dark:text-[#f7d774]"
                  >
                    {t.fatherFullName} <span className="text-red-600">*</span>
                  </label>
                  <input
                    id="fatherFullName"
                    type="text"
                    value={form.fatherFullName}
                    onChange={(e) =>
                      setForm({ ...form, fatherFullName: e.target.value })
                    }
                    placeholder={t.fatherFullNamePlaceholder}
                    required
                    className="w-full rounded-xl border border-[#d9ad55] bg-white px-4 py-3 text-[#3f0008] outline-none transition focus:border-[#b9161f] focus:ring-2 focus:ring-[#d9ad55]/30 dark:border-[#9b0f16] dark:bg-[#2a0508] dark:text-white"
                  />
                </div>

                <div>
                  <label
                    htmlFor="motherFullName"
                    className="mb-2 block text-sm font-semibold text-[#5b3a00] dark:text-[#f7d774]"
                  >
                    {t.motherFullName} <span className="text-red-600">*</span>
                  </label>
                  <input
                    id="motherFullName"
                    type="text"
                    value={form.motherFullName}
                    onChange={(e) =>
                      setForm({ ...form, motherFullName: e.target.value })
                    }
                    placeholder={t.motherFullNamePlaceholder}
                    required
                    className="w-full rounded-xl border border-[#d9ad55] bg-white px-4 py-3 text-[#3f0008] outline-none transition focus:border-[#b9161f] focus:ring-2 focus:ring-[#d9ad55]/30 dark:border-[#9b0f16] dark:bg-[#2a0508] dark:text-white"
                  />
                </div>

                <div>
                  <label
                    htmlFor="whatsappNumber"
                    className="mb-2 block text-sm font-semibold text-[#5b3a00] dark:text-[#f7d774]"
                  >
                    {t.whatsappNumber}
                    <span className="ml-2 text-xs font-normal text-gray-500 dark:text-gray-400">
                      (Optional)
                    </span>
                  </label>
                  <input
                    id="whatsappNumber"
                    type="tel"
                    value={form.whatsappNumber}
                    onChange={(e) =>
                      setForm({ ...form, whatsappNumber: e.target.value })
                    }
                    placeholder={t.whatsappNumberPlaceholder}
                    className="w-full rounded-xl border border-[#d9ad55] bg-white px-4 py-3 text-[#3f0008] outline-none transition focus:border-[#b9161f] focus:ring-2 focus:ring-[#d9ad55]/30 dark:border-[#9b0f16] dark:bg-[#2a0508] dark:text-white"
                  />
                </div>
                <div>
                  <label
                    htmlFor="email"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.email} *
                  </label>

                  <input
                    id="email"
                    type="email"
                    value={form.email}
                    onChange={(e) =>
                      updateField(
                        "email",
                        e.target.value
                      )
                    }
                    placeholder={t.emailPlaceholder}
                    autoComplete="email"
                    required
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none transition-colors placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50 dark:focus:border-red-300 dark:focus:ring-red-300/20"
                  />
                </div>

                <div>
                  <label
                    htmlFor="phone"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.phone}
                  </label>

                  <input
                    id="phone"
                    type="tel"
                    value={form.phone}
                    onChange={(e) =>
                      updateField(
                        "phone",
                        e.target.value
                      )
                    }
                    placeholder={t.phonePlaceholder}
                    autoComplete="tel"
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none transition-colors placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50 dark:focus:border-red-300 dark:focus:ring-red-300/20"
                  />
                </div>

                <div>
                  <label
                    htmlFor="gender"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.gender}
                  </label>

                  <CustomDropdown
  id="gender"
  value={form.gender}
  placeholder={t.genderPlaceholder}
  options={[
    {
      value: "Male",
      label: t.male,
    },
    {
      value: "Female",
      label: t.female,
    },
    {
      value: "Other",
      label: t.other,
    },
  ]}
  onChange={(value) => {
    updateField("gender", value);
  }}
/>
                </div>

                <div>
                  <label
                    htmlFor="dateOfBirth"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.dateOfBirth}
                  </label>

                  <input
                    id="dateOfBirth"
                    type="date"
                    value={form.dateOfBirth}
                    onChange={(e) =>
                      updateField(
                        "dateOfBirth",
                        e.target.value
                      )
                    }
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:focus:border-red-300 dark:focus:ring-red-300/20"
                  />
                </div>
              </div>
            </section>

            <section>
              <h2 className="mb-4 border-b border-gray-200 pb-2 text-lg font-semibold text-gray-900 dark:border-red-300/20 dark:text-red-50">
                {t.addressInformation}
              </h2>

              <div className="space-y-5">
                <div>
                  <label
                    htmlFor="address"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.address}
                  </label>

                  <textarea
                    id="address"
                    value={form.address}
                    onChange={(e) =>
                      updateField(
                        "address",
                        e.target.value
                      )
                    }
                    placeholder={t.addressPlaceholder}
                    rows={3}
                    className="w-full resize-none rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50"
                  />
                </div>

                <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

  {/* Country */}
  <div>
    <label
      htmlFor="country"
      className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
    >
      {t.country}
    </label>

    <CustomDropdown
      id="country"
      value={countryCode}
      placeholder={t.countryPlaceholder}
      disabled={loadingCountries}
      options={countries.map((country) => ({
        value: country.iso2,
        label: country.name,
      }))}
      onChange={(value) => {
        const selectedCountry = countries.find(
          (country) => country.iso2 === value
        );

        setCountryCode(value);

        setForm((prev) => ({
          ...prev,
          country: selectedCountry?.name || "",
          state: "",
          city: "",
        }));
      }}
    />
  </div>

  {/* State */}
  <div>
    <label
      htmlFor="state"
      className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
    >
      {t.state}
    </label>

    <CustomDropdown
      id="state"
      value={stateCode}
      placeholder={t.statePlaceholder}
      disabled={!countryCode || loadingStates}
      options={states.map((state) => ({
        value: state.iso2 || state.state_code || state.name,
        label: state.name,
      }))}
      onChange={(value) => {
        const selectedState = states.find(
          (state) =>
            (state.iso2 || state.state_code || state.name) === value
        );

        setStateCode(value);

        setForm((prev) => ({
          ...prev,
          state: selectedState?.name || "",
          city: "",
        }));
      }}
    />
  </div>

  {/* City */}
  <div>
    <label
      htmlFor="city"
      className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
    >
      {t.city}
    </label>

    <CustomDropdown
      id="city"
      value={form.city}
      placeholder={t.cityPlaceholder}
      disabled={!stateCode || loadingCities}
      options={cities.map((city) => ({
        value: city.name,
        label: city.name,
      }))}
      onChange={(value) => {
        updateField("city", value);
      }}
    />
  </div>

  {/* Post Code */}
  <div>
    <label
      htmlFor="pincode"
      className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
    >
      {t.pincode}
    </label>

    <input
      id="pincode"
      type="text"
      value={form.pincode}
      onChange={(e) =>
        updateField("pincode", e.target.value)
      }
      placeholder={t.pincodePlaceholder}
      inputMode="numeric"
      className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50"
    />
  </div>

</div>
</div>
            </section>

            <section>
              <h2 className="mb-4 border-b border-gray-200 pb-2 text-lg font-semibold text-gray-900 dark:border-red-300/20 dark:text-red-50">
                {t.accountSecurity}
              </h2>

              <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <div>
                  <label
                    htmlFor="password"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.password} *
                  </label>

                  <input
                    id="password"
                    type="password"
                    value={form.password}
                    onChange={(e) =>
                      updateField(
                        "password",
                        e.target.value
                      )
                    }
                    placeholder={t.passwordPlaceholder}
                    autoComplete="new-password"
                    required
                    minLength={8}
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50"
                  />
                </div>

                <div>
                  <label
                    htmlFor="confirmPassword"
                    className="mb-2 block text-sm font-semibold text-gray-700 dark:text-red-50"
                  >
                    {t.confirmPassword} *
                  </label>

                  <input
                    id="confirmPassword"
                    type="password"
                    value={form.confirmPassword}
                    onChange={(e) =>
                      updateField(
                        "confirmPassword",
                        e.target.value
                      )
                    }
                    placeholder={
                      t.confirmPasswordPlaceholder
                    }
                    autoComplete="new-password"
                    required
                    minLength={8}
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-3 text-gray-900 outline-none placeholder:text-gray-400 focus:border-red-700 focus:ring-2 focus:ring-red-100 dark:border-red-300/30 dark:bg-[#51101a] dark:text-white dark:placeholder:text-red-100/50"
                  />
                </div>
              </div>
            </section>

            {error && (
              <div className="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-300/30 dark:bg-red-950/30 dark:text-red-200">
                {error}
              </div>
            )}

            {success && (
              <div className="rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700 dark:border-green-300/30 dark:bg-green-950/30 dark:text-green-200">
                {success}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full rounded-lg bg-red-800 px-4 py-3 font-semibold text-white transition hover:bg-red-900 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-red-600 dark:hover:bg-red-500"
            >
              {loading
                ? t.creatingAccount
                : t.createAccount}
            </button>
          </form>

          <div className="mt-6 text-center text-sm text-gray-600 dark:text-red-100/70">
            {t.alreadyAccount}{" "}
            <Link
              href={`/${locale}/login`}
              className="font-semibold text-red-700 hover:underline dark:text-red-300"
            >
              {t.signIn}
            </Link>
          </div>

          <div className="mt-4 text-center text-xs text-gray-500 dark:text-red-100/50">
            {t.approvalNotice}
          </div>
        </div>
      </div>
    </main>
  );
}